{
  "predictors": [
    {
      "name": "Employee Growth Rate",
      "construction": "Current employee count minus employee count from one year ago, divided by employee count from one year ago.",
      "rationale": "Firms that are rapidly growing their workforce may be expanding operations or increasing capacity, indicating future revenue growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Advertising Intensity Change",
      "construction": "Current advertising expense divided by total sales, compared to the same ratio one year ago.",
      "rationale": "An increase in advertising intensity can signal a proactive strategy to capture market share, potentially leading to higher future sales.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Spending Consistency",
      "construction": "Standard deviation of R&D expenses over the previous four quarters divided by average R&D expenses over the same period.",
      "rationale": "Consistent R&D spending might indicate a stable and ongoing commitment to innovation, which could lead to sustained competitive advantages.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Cash Conversion Efficiency",
      "construction": "Operating cash flow divided by net income over the past year.",
      "rationale": "A higher ratio suggests that a company is efficient at converting its profits into cash, which can be reinvested into business growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Dividend Growth Stability",
      "construction": "Standard deviation of dividend per share growth rate over the past five years.",
      "rationale": "Stable growth in dividends might reflect a company's strong and predictable earnings, which can be attractive to investors.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Supplier Diversity",
      "construction": "Number of unique suppliers over the past year, divided by total purchases.",
      "rationale": "A diverse supplier base can reduce dependency on individual suppliers, mitigating risk and potential supply chain disruptions.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Capital Reinvestment Rate",
      "construction": "Capital expenditures divided by depreciation expense over the past year.",
      "rationale": "A high reinvestment rate may signal that a firm is actively investing in future growth and modernization of its assets.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "International Revenue Exposure",
      "construction": "Revenue from international operations divided by total revenue over the past year.",
      "rationale": "Firms with significant international exposure may benefit from global diversification and growth opportunities in emerging markets.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Technological Adoption Rate",
      "construction": "Annual spending on information technology upgrades divided by total assets.",
      "rationale": "Firms investing in new technology may improve operational efficiency and gain a competitive edge in their industry.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Policy Score",
      "construction": "Qualitative assessment score based on environmental initiatives and compliance disclosures, normalized over the past year.",
      "rationale": "Companies with better environmental policies may be well-positioned for regulatory changes and potentially attract socially conscious investors.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
